sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.filter = 'all';

    c.setFilter = function(filter) {
        c.filter = filter;
    };

    c.filteredBookings = function() {
        if (c.filter == 'all') {
            return $scope.data.bookings;
        }
        return $scope.data.bookings.filter(function(b) {
            return b.status == c.filter;
        });
    };
};

sp_widget.css:
.my-bookings {
  margin-top: 25px;
  background: white;
  border-radius: 12px;
  padding: 25px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);

  h3 {
    color: #00695C;
    font-weight: bold;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #00695C;
  }

  .booking-tabs {
    display: flex;
    gap: 10px;

    .tab-btn {
      padding: 8px 20px;
      border-radius: 20px;
      border: 1px solid #00695C;
      background: white;
      color: #00695C;
      cursor: pointer;

      &.active {
        background: #00695C;
        color: white;
      }

      &:hover {
        background: #E0F2F1;
      }
    }
  }

  .bookings-table {
    thead tr {
      background: #00695C;

      th {
        color: white;
        font-weight: bold;
        border: none;
        padding: 12px 15px;
      }
    }

    tbody tr {
      &:hover {
        background: #E0F2F1;
      }

      td {
        padding: 12px 15px;
        vertical-align: middle;
      }
    }
  }

  .status-badge {
    padding: 4px 12px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: bold;

    &.badge-pending {
      background: #FFF3E0;
      color: #E65100;
    }

    &.badge-approved {
      background: #E8F5E9;
      color: #2E7D32;
    }

    &.badge-rejected {
      background: #FFEBEE;
      color: #C62828;
    }
  }
}

sp_widget.script:
(function() {
    var gr = new GlideRecord(
        'x_1954179_sports_0_sports_hall_booking'
    );
    gr.addQuery('requested_by', gs.getUserID());
    gr.orderByDesc('sys_created_on');
    gr.query();

    data.bookings = [];
    while (gr.next()) {
        data.bookings.push({
            number: gr.getValue('number'),
            hall: gr.getDisplayValue('sports_hall'),
            startDate: gr.getDisplayValue('start_date'),
            endDate: gr.getDisplayValue('end_date'),
            purpose: gr.getValue('purpose'),
            status: gr.getValue('status')
        });
    }
})();
